const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const southernSpain = ee.Geometry.Polygon([
    [[-7.5, 35.5], [-7.5, 38.5], [-1.5, 38.5], [-1.5, 35.5], [-7.5, 35.5]]
  ]);

  const startDate = '2023-04-01';
  const endDate = '2023-04-30';
  const thresholdC = 32.22; // 90°F in Celsius

  // 2. Data Acquisition & Check
  let tempCollection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(southernSpain)
    .select('temperature_2m');

  const collectionSize = tempCollection.size().getInfo();
  console.log(`Collection size: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No data found for April 2023 in southern Spain.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Get maximum temperature
  // ERA5 temperature is in Kelvin, convert to Celsius
  tempCollection = tempCollection.map(function(img) {
    return img.subtract(273.15);
  });

  const maxTemp = tempCollection.max();

  // 4. Calculate statistics
  const stats = maxTemp.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: southernSpain,
    scale: 11132,
    maxPixels: 1e9
  }).getInfo();

  const maxTempValue = stats.temperature_2m;

  // Also check pixel count
  const pixelCount = maxTemp.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: southernSpain,
    scale: 11132,
    maxPixels: 1e9
  }).getInfo().temperature_2m;

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Validation & Final Answer
  console.log(`Maximum temperature in April 2023: ${maxTempValue !== null ? maxTempValue.toFixed(2) : 'null'}°C`);
  console.log(`Threshold: ${thresholdC.toFixed(2)}°C (90°F)`);

  if (maxTempValue === null || maxTempValue === undefined || isNaN(maxTempValue)) {
    console.log('Calculation failed - invalid temperature value.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (maxTempValue < -50 || maxTempValue > 60) {
    console.log('Temperature value outside reasonable range.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (maxTempValue >= thresholdC) {
    console.log(`Yes, temperatures exceeded 90°F (${maxTempValue.toFixed(2)}°C)`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`No, maximum temperature was ${maxTempValue.toFixed(2)}°C, below 90°F threshold`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
